I'll design with the knowledge I have. Rating chips will use `Chip` with `onClick`, wrapped in a `role="radiogroup"` for accessibility. Chip is a div, so I'll use `ToggleButton` (a real button) with `role="radio"` and `aria-checked` instead, which keeps keyboard access solid.

The final page:

```tsx
"use client";

import { useCallback, useId, useRef, useState } from "react";
import type { FormEvent, KeyboardEvent } from "react";
import {
  Button,
  Column,
  Dialog,
  Heading,
  IconButton,
  Row,
  Text,
  Textarea,
  ToggleButton,
  useToast,
} from "@once-ui-system/core";
import type { IconName } from "@once-ui-system/core";

interface Rating {
  value: number;
  label: string;
  icon: IconName;
}

const RATINGS: readonly Rating[] = [
  { value: 1, label: "Poor", icon: "dislike" },
  { value: 2, label: "Fair", icon: "warning" },
  { value: 3, label: "Okay", icon: "smiley" },
  { value: 4, label: "Good", icon: "like" },
  { value: 5, label: "Great", icon: "heart" },
];

const TOPICS: readonly string[] = [
  "Billing",
  "Performance",
  "Design",
  "Documentation",
  "Integrations",
];

const MAX_LENGTH = 500;

const HIGHLIGHTS: readonly { title: string; body: string; icon: IconName }[] = [
  {
    title: "Faster deploys",
    body: "Median build time dropped from 4m 12s to 1m 48s after last week's cache rework.",
    icon: "bolt",
  },
  {
    title: "Shared dashboards",
    body: "Invite teammates with view-only links and keep sensitive widgets hidden per role.",
    icon: "barChart",
  },
  {
    title: "Audit history",
    body: "Every change to a project is logged for 90 days, with who, what and when.",
    icon: "clipboard",
  },
];

export default function Page() {
  const { addToast } = useToast();
  const [open, setOpen] = useState(false);
  const [rating, setRating] = useState<number | null>(null);
  const [topic, setTopic] = useState<string | null>(null);
  const [message, setMessage] = useState("");
  const [ratingError, setRatingError] = useState(false);
  const [submitting, setSubmitting] = useState(false);

  const textareaId = useId();
  const ratingLabelId = useId();
  const topicLabelId = useId();
  const ratingRefs = useRef<(HTMLButtonElement | null)[]>([]);
  const topicRefs = useRef<(HTMLButtonElement | null)[]>([]);
  const triggerRef = useRef<HTMLDivElement | null>(null);

  const reset = useCallback(() => {
    setRating(null);
    setTopic(null);
    setMessage("");
    setRatingError(false);
    setSubmitting(false);
  }, []);

  const handleClose = useCallback(() => {
    setOpen(false);
    // Return focus to the floating trigger once the dialog has unmounted.
    window.setTimeout(() => {
      triggerRef.current?.querySelector("button")?.focus();
    }, 0);
  }, []);

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (submitting) return;
    if (rating === null) {
      setRatingError(true);
      ratingRefs.current[0]?.focus();
      return;
    }
    setSubmitting(true);
    // Simulated network round trip.
    window.setTimeout(() => {
      const picked = RATINGS.find((r) => r.value === rating);
      addToast({
        variant: "success",
        message: `Thanks for your feedback! You rated us "${picked?.label ?? rating}".`,
        duration: 5000,
      });
      reset();
      handleClose();
    }, 700);
  };

  // Roving radio-group keyboard handling (arrow keys move + select).
  const handleRadioKeys = (
    event: KeyboardEvent<HTMLElement>,
    index: number,
    count: number,
    refs: React.MutableRefObject<(HTMLButtonElement | null)[]>,
    select: (i: number) => void,
  ) => {
    let next = index;
    if (event.key === "ArrowRight" || event.key === "ArrowDown") next = (index + 1) % count;
    else if (event.key === "ArrowLeft" || event.key === "ArrowUp") next = (index - 1 + count) % count;
    else if (event.key === "Home") next = 0;
    else if (event.key === "End") next = count - 1;
    else return;
    event.preventDefault();
    select(next);
    refs.current[next]?.focus();
  };

  const selectedRating = RATINGS.find((r) => r.value === rating);
  const ratingTabStop = rating === null ? 0 : RATINGS.findIndex((r) => r.value === rating);
  const topicTabStop = topic === null ? 0 : TOPICS.indexOf(topic);

  return (
    <Column as="main" fillWidth horizontal="center" paddingX="24" paddingY="64" s={{ paddingY: "40", paddingX: "16" }}>
      <Column maxWidth="m" gap="40">
        <Column gap="16">
          <Text variant="label-default-s" onBackground="brand-medium">
            Product update · March
          </Text>
          <Heading as="h1" variant="display-strong-s">
            What&apos;s new in Northwind Cloud
          </Heading>
          <Text variant="body-default-l" onBackground="neutral-weak">
            Three changes shipped this month. Tried them out? Tell us how they landed using the feedback button in
            the corner of your screen. We read every message.
          </Text>
        </Column>

        <Column gap="16">
          {HIGHLIGHTS.map((item) => (
            <Row
              key={item.title}
              background="surface"
              border
              radius="l"
              padding="24"
              gap="16"
              vertical="start"
            >
              <Row
                center
                background="brand-alpha-weak"
                radius="m"
                minWidth={40}
                minHeight={40}
                onBackground="brand-strong"
                aria-hidden="true"
              >
                <IconButton icon={item.icon} variant="ghost" size="m" disabled ariaLabel={item.title} />
              </Row>
              <Column gap="8" fillWidth>
                <Heading as="h2" variant="heading-strong-m">
                  {item.title}
                </Heading>
                <Text variant="body-default-m" onBackground="neutral-weak">
                  {item.body}
                </Text>
              </Column>
            </Row>
          ))}
        </Column>
      </Column>

      {/* Floating trigger */}
      <Row
        ref={triggerRef}
        position="fixed"
        bottom="24"
        right="24"
        s={{ bottom: "16", right: "16" }}
        style={{ zIndex: 20 }}
      >
        <Button
          variant="primary"
          size="l"
          rounded
          prefixIcon="chat"
          label="Feedback"
          data-border="rounded"
          aria-haspopup="dialog"
          onClick={() => setOpen(true)}
        />
      </Row>

      <Dialog
        open={open}
        onClose={handleClose}
        title="Send us feedback"
        description="Your input shapes what we build next. It takes under a minute."
        footer={
          <Row gap="12" horizontal="end" fillWidth wrap>
            <Button variant="tertiary" label="Cancel" onClick={handleClose} disabled={submitting} />
            <Button
              variant="primary"
              label={submitting ? "Sending…" : "Send feedback"}
              prefixIcon="send"
              loading={submitting}
              onClick={() => {
                const form = document.getElementById("feedback-form");
                if (form instanceof HTMLFormElement) form.requestSubmit();
              }}
            />
          </Row>
        }
      >
        <form id="feedback-form" onSubmit={handleSubmit} noValidate>
          <Column gap="24" paddingY="8">
            <Column gap="12">
              <Text id={ratingLabelId} variant="label-default-m">
                How was your experience?
              </Text>
              <Row
                role="radiogroup"
                aria-labelledby={ratingLabelId}
                aria-required="true"
                aria-invalid={ratingError}
                gap="8"
                wrap
              >
                {RATINGS.map((item, index) => {
                  const selected = rating === item.value;
                  return (
                    <ToggleButton
                      key={item.value}
                      ref={(node: HTMLButtonElement | null) => {
                        ratingRefs.current[index] = node;
                      }}
                      role="radio"
                      aria-checked={selected}
                      tabIndex={index === ratingTabStop ? 0 : -1}
                      variant="outline"
                      selected={selected}
                      prefixIcon={item.icon}
                      label={item.label}
                      radius="full"
                      onClick={() => {
                        setRating(item.value);
                        setRatingError(false);
                      }}
                      onKeyDown={(e: KeyboardEvent<HTMLElement>) =>
                        handleRadioKeys(e, index, RATINGS.length, ratingRefs, (i) => {
                          setRating(RATINGS[i].value);
                          setRatingError(false);
                        })
                      }
                    />
                  );
                })}
              </Row>
              <Text variant="body-default-s" onBackground={ratingError ? "danger-medium" : "neutral-weak"} role={ratingError ? "alert" : undefined}>
                {ratingError
                  ? "Please choose a rating before sending."
                  : selectedRating
                    ? `You selected ${selectedRating.value} of 5: ${selectedRating.label}.`
                    : "1 is poor, 5 is great."}
              </Text>
            </Column>

            <Column gap="12">
              <Text id={topicLabelId} variant="label-default-m">
                What is it about? <Text as="span" variant="label-default-s" onBackground="neutral-weak">(optional)</Text>
              </Text>
              <Row role="radiogroup" aria-labelledby={topicLabelId} gap="8" wrap>
                {TOPICS.map((name, index) => {
                  const selected = topic === name;
                  return (
                    <ToggleButton
                      key={name}
                      ref={(node: HTMLButtonElement | null) => {
                        topicRefs.current[index] = node;
                      }}
                      role="radio"
                      aria-checked={selected}
                      tabIndex={index === topicTabStop ? 0 : -1}
                      variant="subtle"
                      size="s"
                      selected={selected}
                      label={name}
                      radius="full"
                      onClick={() => setTopic(selected ? null : name)}
                      onKeyDown={(e: KeyboardEvent<HTMLElement>) =>
                        handleRadioKeys(e, index, TOPICS.length, topicRefs, (i) => setTopic(TOPICS[i]))
                      }
                    />
                  );
                })}
              </Row>
            </Column>

            <Textarea
              id={textareaId}
              label="Tell us more"
              placeholder="What worked well? What would you change?"
              lines={4}
              resize="vertical"
              value={message}
              maxLength={MAX_LENGTH}
              characterCount
              description={`Up to ${MAX_LENGTH} characters.`}
              onChange={(e: React.ChangeEvent<HTMLTextAreaElement>) => setMessage(e.target.value)}
            />
          </Column>
        </form>
      </Dialog>
    </Column>
  );
}
```

I wrote that without first confirming some prop types (`ref` on `Row`/`ToggleButton`, `value`/`maxLength` on `Textarea`, `position="fixed"`, `role` on `Text`). I'll verify those before finalizing.

